import { USERS, expect, test, uniqueName } from "../../fixtures";

test.describe("vendor audit trail", () => {
  test(
    "audit events are listed oldest first with actor and action",
    { tag: "@AUD-01" },
    async ({ apiAs }) => {
      // Arrange: a member creates a vendor and uploads a W-9 for it
      const member = await apiAs("member");

      const createResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("Audit Trail Vendor"),
          category: "services",
          contact_email: `billing+${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@audit-vendor.test`,
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendor = await createResponse.json();

      const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "w9",
          file: {
            name: "w9.pdf",
            mimeType: "application/pdf",
            buffer: Buffer.from("%PDF-1.4\n% W-9 test document\n%%EOF\n"),
          },
        },
      });
      expect(uploadResponse.status()).toBe(201);

      // Act + Assert: extraction may finish asynchronously, so poll the trail
      // until the expected sequence of actions appears.
      const expectedActions = ["vendor.created", "document.uploaded", "document.extracted"];
      let trail: { items: Array<{ action: string; actor: { email: string; name: string; id: string }; at: string }> } =
        { items: [] };

      await expect
        .poll(
          async () => {
            const response = await member.get(`/api/vendors/${vendor.id}/audit`);
            expect(response.status()).toBe(200);
            trail = await response.json();
            return trail.items.map((event) => event.action);
          },
          { timeout: 30_000, intervals: [500, 1000, 2000] },
        )
        .toEqual(expectedActions);

      // Each event names the actor and a timestamp
      for (const event of trail.items) {
        expect(event.actor.id).toBeTruthy();
        expect(event.actor.name).toBeTruthy();
        expect(event.actor.email).toBe(USERS.member);
        expect(Number.isNaN(Date.parse(event.at))).toBe(false);
      }

      // Oldest first: timestamps are non-decreasing
      const times = trail.items.map((event) => Date.parse(event.at));
      for (let i = 1; i < times.length; i++) {
        expect(times[i]).toBeGreaterThanOrEqual(times[i - 1]);
      }
    },
  );
});
